        <div v-if="tab === 'contents' || tab === 'preview'" class="stock-check-controls">
          <div class="stock-check-heading"><b>新增福袋库存预检</b><span class="hint">每仓独立检查，组件按件计算；已被其他业务占用的库存不能重复用于新增福袋。</span></div>
          <template v-if="canCheckStock">
            <div class="stock-check-inputs"><label>检查仓库</label><el-select v-model="trialStores" multiple filterable :multiple-limit="20" placeholder="选择检查仓库" style="min-width:280px;max-width:100%"><el-option v-for="w in warehouses" :key="w.wmsSimulationCode" :label="`${w.wmsSimulationName} · ${w.wmsSimulationCode}`" :value="w.wmsSimulationCode"/></el-select><template v-if="form.mode !== 'PRESET'"><label>预检袋数</label><el-input-number v-model="trialQuantity" :min="1" :max="5000" :precision="0" size="small"/></template><span v-else>本批 {{ form.preset_quantity || '待设置' }} 袋</span><el-button size="small" :loading="stockLoading" :disabled="!stockScope" @click="refreshStock">刷新库存</el-button><el-button v-if="tab === 'contents'" size="small" @click="tab = 'preview'">检查组合与成本</el-button></div>
            <p v-if="!trialStores.length" class="hint">请选择检查仓库，选择后自动查询。调整袋数或配额会立即重算缺口，无需重新查询库存。</p>
            <p v-else-if="!skus.length" class="hint">请先添加候选商品，添加后自动检查库存。</p>
            <p v-else-if="stockLoading" class="hint">正在批量检查组件库存，尚不能判断是否缺货……</p>
            <el-alert v-if="stockError" :title="stockError" type="error" :closable="false" show-icon/>
            <template v-if="stockViews.length"><p class="hint">检查时间：{{ stockCheckedAt }} <b v-if="stockStale" class="stock-warning">结果已超过30秒，请刷新；下方缺口按上次库存计算。</b><span v-else>（只读快照，实际分货重新校验并锁库）</span></p><div class="stock-warehouse-choices"><el-button v-for="s in stockViews" :key="s.store_code" size="small" :type="activeStockStore === s.store_code ? 'primary' : ''" @click="activeStockStore = s.store_code">{{ s.store_code }} · {{ s.code === 'STOCK_SHORTAGE' ? `缺${s.shortage}件` : s.code === 'STOCK_READY' ? '数量满足' : s.code === 'CHECK_FAILED' ? '查询失败' : '配置待调整' }}</el-button></div></template>
            <el-alert v-if="activeStockCheck" :title="activeStockCheck.message" :type="activeStockCheck.code === 'STOCK_SHORTAGE' ? 'warning' : 'info'" :closable="false" show-icon/>
            <el-alert v-if="activeStockFailure" :title="`${activeStockStore}：检查失败，不能判断是否缺货`" :description="activeStockFailure.message" type="error" :closable="false" show-icon/>
          </template>
          <el-alert v-else title="当前账号没有库存查询权限，无法检查库存；可联系有权限的同事核对。" type="info" :closable="false"/>
          <el-alert v-if="warehouseError" title="仓库资料未能加载，请检查查询权限后重试。" type="warning" :closable="false"><el-button type="text" @click="loadWarehouses">重新加载仓库</el-button></el-alert>
        </div>
        <el-tabs v-model="tab">
          <el-tab-pane label="基本设置" name="basic">
            <h3>选择何时确定每袋内容</h3>
            <el-form label-position="top" :disabled="!canEdit || busy">
              <el-form-item label="运行状态"><el-radio-group v-model="form.enabled"><el-radio :label="1">启用</el-radio><el-radio :label="0">停用新增配货与投放</el-radio></el-radio-group><p class="hint">已付款或在途订单仍使用原保障来源；库存回收请在原分货来源中处理。</p></el-form-item>
              <el-form-item label="每袋内容确定方式"><div class="mode-choices"><label :class="{ selected: form.mode === 'RANDOM' }"><el-radio v-model="form.mode" label="RANDOM">下单时确定内容</el-radio><p>分货时先锁定组件库存；订单进入后，从已锁定商品中逐袋选品，确定后保持不变。</p></label><label :class="{ selected: form.mode === 'PRESET' }"><el-radio v-model="form.mode" label="PRESET">分货时预先确定内容</el-radio><p>分货时生成每袋组合并锁定组件库存；订单直接领取已有组合。支持每批固定袋数和每袋成本上限。</p></label></div><p class="hint">两种方式都先保障组件库存，仓库按实际商品发货。预先生成组合不代表仓库已提前装袋。</p></el-form-item>
              <el-form-item label="商品选择规则"><el-radio-group v-model="form.selection"><el-radio label="WEIGHTED">按权重随机</el-radio><el-radio label="CLEARANCE">清仓优先</el-radio></el-radio-group><p class="hint">权重表示相对选中倾向，实际选择受可用库存限制。清仓模式先比较候选优先级，再优先使用较早入库的批次。</p></el-form-item>
            </el-form>
          </el-tab-pane>
          <el-tab-pane label="内容规则" name="contents">
            <div class="section-heading"><div><h3>每组选1件，组成完整福袋</h3><p class="hint">最多10组、200个候选SKU；组间SKU不重叠。仅选普通实物商品。</p></div><el-button v-if="canEdit" size="small" :disabled="form.groups.length >= 10 || busy" @click="addGroup">添加分组</el-button></div>
            <div v-if="form.mode === 'PRESET'" class="batch-settings"><label for="lucky-batch-quantity">每批生成袋数</label><el-input-number id="lucky-batch-quantity" v-model="form.preset_quantity" :min="1" :max="5000" :precision="0" size="small" :disabled="!canEdit || busy"/><span>袋</span><p class="hint">每个分组都必须覆盖完整的一批袋数，各组分别计算，不是把各组数量相加。这里填写的是组合生成数量，不是商品库存。</p></div>
            <el-empty v-if="!form.groups.length" description="添加第一个商品分组" :image-size="65" />
            <article v-for="(g, index) in form.groups" :key="g.key" class="group-card">
              <div class="group-heading"><el-input v-model="g.name" :disabled="!canEdit || busy" maxlength="50" :placeholder="`分组${index + 1}，例如上装`"/><el-tag size="small">每袋选1件</el-tag><el-button v-if="canEdit" type="text" :disabled="busy" @click="form.groups.splice(index, 1)">删除分组</el-button></div>
              <div v-if="form.mode === 'PRESET'" class="quota-summary"><span>每批 <b>{{ quotaSummaries[index].batch || '待设置' }}</b> 袋</span><span>已固定 <b>{{ quotaSummaries[index].fixed }}</b> 袋</span><span>剩余 <b>{{ Math.max(0, quotaSummaries[index].remaining || 0) }}</b> 袋</span><span>参与剩余分配 <b>{{ quotaSummaries[index].flexible }}</b> 种商品</span></div>
              <el-table :data="g.candidates" size="small" empty-text="选择本组的候选商品">
                <el-table-column label="商品 / SKU" min-width="200"><template slot-scope="s"><b>{{ s.row.goods_name || s.row.sku_sn }}</b><div class="hint">{{ s.row.sku_sn }}</div></template></el-table-column>
                <el-table-column label="本批需要" width="95"><template slot-scope="s">{{ form.mode === 'PRESET' && s.row.fixed_quantity != null ? `${s.row.fixed_quantity}件` : '按组分配' }}</template></el-table-column>
                <el-table-column label="本仓可用" width="95"><template slot-scope="s"><el-tooltip v-if="stockRow(s.row)" :content="stockExplanation(stockRow(s.row))" placement="top"><span>{{ stockRow(s.row).available }}件</span></el-tooltip><span v-else class="hint">{{ stockLoading ? '检查中' : stockError || activeStockFailure ? '查询失败' : '未检查' }}</span></template></el-table-column>
                <el-table-column label="库存缺口" width="110"><template slot-scope="s"><b v-if="stockRow(s.row) && stockRow(s.row).shortage > 0" class="stock-shortage">缺{{ stockRow(s.row).shortage }}件</b><span v-else-if="stockRow(s.row)">{{ stockRow(s.row).mode === 'AUTO' ? '见分组缺口' : stockRow(s.row).mode === 'EXCLUDE' ? '不选' : '数量充足' }}</span><span v-else class="hint">待检查</span></template></el-table-column>
                <el-table-column label="随机权重" width="145"><template slot-scope="s"><el-input-number v-model="s.row.weight" size="small" :min="1" :max="10000" :precision="0" :disabled="!canEdit || busy"/></template></el-table-column>
                <el-table-column v-if="form.selection === 'CLEARANCE'" label="清仓优先级" width="145"><template slot-scope="s"><el-input-number v-model="s.row.clearance_priority" size="small" :min="0" :max="10000" :precision="0" :disabled="!canEdit || busy"/></template></el-table-column>
                <el-table-column v-if="form.mode === 'PRESET'" label="每批如何分配该商品" width="240"><template slot-scope="s"><el-select :value="quotaMode(s.row)" size="small" :disabled="!canEdit || busy" @change="setQuotaMode(s.row, $event)"><el-option label="按规则分配剩余" value="AUTO"/><el-option label="固定袋数" value="FIXED"/><el-option label="不选该商品" value="EXCLUDE"/></el-select><div v-if="quotaMode(s.row) === 'FIXED'" class="quota-input"><el-input-number v-model="s.row.fixed_quantity" size="small" :min="1" :max="5000" :precision="0" :controls="false" :disabled="!canEdit || busy"/><span>袋／批</span></div><p v-else class="hint quota-row-hint">{{ quotaMode(s.row) === 'AUTO' ? '参与本组剩余袋数的分配' : '每批都不选，与库存是否充足无关' }}</p></template></el-table-column>
                <el-table-column label="操作" width="95"><template slot-scope="s"><router-link target="_blank" :to="{path:'/oms-inventory/productInventory',query:{skuSn:s.row.sku_sn}}">查看库存</router-link><el-button v-if="canEdit" type="text" :disabled="busy" @click="g.candidates.splice(s.$index, 1)">移除</el-button></template></el-table-column>
              </el-table>
              <el-alert v-if="form.mode === 'PRESET'" class="quota-feedback" :title="quotaSummaries[index].issue || !activeStockCheck ? quotaSummaries[index].title : '配额设置通过；库存预检结果见商品及分组缺口'" :description="quotaSummaries[index].issue || !activeStockCheck ? quotaSummaries[index].message : '配额正确只表示每批袋数分配完整，不代表库存充足或每袋成本已通过。'" :type="quotaSummaries[index].issue ? 'error' : 'info'" :closable="false" show-icon/>
              <p v-if="groupStock(g)" class="group-stock-feedback" :class="{'stock-shortage':groupStock(g).shortage > 0}">{{ activeStockStore }}：本组固定商品缺{{ groupStock(g).fixed_shortage }}件；按规则分配的部分需要{{ groupStock(g).flexible_required }}件、候选可用{{ groupStock(g).flexible_available }}件，缺{{ groupStock(g).flexible_shortage }}件。{{ configurationIssue ? '请先完成配置，再确认库存结论。' : stockStale ? '库存快照已过期，请刷新。' : '组件数量预检不代表逐袋成本已通过。' }}</p>
              <el-button v-if="canEdit" size="small" :disabled="busy || skus.length >= 200" @click="openPicker(g)">选择候选商品</el-button>
            </article>
          </el-tab-pane>
          <el-tab-pane label="库存与履约" name="stock">
            <h3>用实际组件保障销售袋数</h3><lucky-bag-ledger :sku="goods.skuSn" v-if="goods.skuSn"/>
            <el-form label-position="top" :disabled="!canEdit || busy">
              <template v-if="form.mode === 'PRESET'"><p class="hint">每批生成袋数和商品分配在“内容规则”中设置，分货按完整批次创建。</p><el-form-item label="每袋批次成本上限"><el-input-number v-model="form.max_cost" :min="0" :max="100000000" :precision="4" :controls="false"/><span class="unit">元</span><p class="hint">0表示不限制。按实际占用批次的组件成本合计校验，无法满足时整批不创建。</p></el-form-item></template>
              <el-alert v-else-if="Number(form.max_cost) > 0 || hasFixed" title="草稿包含固定袋数或成本上限，请切回“分货时预先确定内容”，或清除这些约束后使用“下单时确定内容”。" type="warning" :closable="false"><el-button type="text" @click="clearConstraints">清除成本上限和固定袋数</el-button></el-alert>
              <el-descriptions :column="1" border><el-descriptions-item label="仓库">在现有分货页选择；每袋同仓配齐。</el-descriptions-item><el-descriptions-item label="渠道分配">在现有分货页按袋分配，系统保护所需组件库存。</el-descriptions-item><el-descriptions-item label="店铺投放">同步福袋父SKU的渠道剩余可售袋数，多链接共享预算。</el-descriptions-item><el-descriptions-item label="实际发货">仓库按确定后的实际SKU和数量执行。</el-descriptions-item><el-descriptions-item label="缺货处理">保留袋数需求等待补足，重试沿用已确定的原组成。</el-descriptions-item></el-descriptions>
            </el-form>
          </el-tab-pane>
          <el-tab-pane label="试算与发布" name="preview">
            <h3>检查仓库库存与成本能否满足配置</h3><p class="hint">先检查配置，再按所选仓库的可用库存和成本约束试算。试算不占用库存，最多展示20袋样本；发布规则也不代表已保障库存，实际分货时重新校验。</p>
            <el-alert :title="configurationIssue ? '配置尚未通过，请先调整设置' : '配置检查通过，库存与成本请以本次试算结果为准'" :description="configurationIssue ? configurationIssue.message : ''" :type="configurationIssue ? 'error' : 'info'" :closable="false" show-icon/>
            <p>完整试算 {{ form.mode === 'PRESET' ? form.preset_quantity : trialQuantity }} 袋。<el-button v-hasPermi="['wmsInventory:inventory:list','ruleStock:info:list']" size="small" :loading="trialBusy" :disabled="busy || !trialStores.length" @click="trial">开始试算</el-button></p>
            <el-alert v-if="trialError" :title="trialError" type="warning" :closable="false"/>
            <article v-for="w in trialResult" :key="w.store_code" class="trial-card"><h4>{{ w.store_code }} <el-tag size="small" :type="w.can_fulfill ? 'success' : 'warning'">{{ w.can_fulfill ? `本次可配齐${w.quantity}袋` : trialStatus(w.code) }}</el-tag></h4><p v-if="w.checked_at" class="hint">本次检查时间：{{ w.checked_at }} <b v-if="trialStale" class="stock-warning">试算已超过30秒，请重新试算；实际分货仍会重新校验。</b></p><template v-if="!w.can_fulfill"><p>{{ w.message }}</p><lucky-bag-trial-diagnostics v-if="w.diagnostics" :diagnostics="w.diagnostics"/><el-button size="small" @click="activeStockStore = w.store_code; tab = 'contents'">返回调整配额</el-button><el-button size="small" @click="focusStockStores">切换检查仓库</el-button></template><template v-else><p>每袋批次成本：¥{{ w.min_cost }} ～ ¥{{ w.max_cost }}</p><el-table :data="w.sample_units" size="small"><el-table-column label="袋序号" prop="unit" width="85"/><el-table-column label="实际组成" min-width="300"><template slot-scope="s">{{ s.row.components.map(c => `${c.goods_name || c.sku_sn}（${c.sku_sn}）×1`).join('、') }}</template></el-table-column><el-table-column label="批次成本" prop="cost" width="110"/></el-table></template></article>
            <el-alert title="发布后形成新版本，已有订单保留原组成和原库存来源。" type="info" :closable="false"/>
          </el-tab-pane>
        </el-tabs>
      </div>
      <aside class="editor-summary"><h3>当前草稿</h3><p>{{ summary }}</p><dl><dt>每袋内容确定方式</dt><dd>{{ form.mode === 'PRESET' ? '分货时预先确定内容' : '下单时确定内容' }}</dd><dt>候选SKU</dt><dd>{{ skus.length }} / 200种</dd><dt>商品选择规则</dt><dd>{{ form.selection === 'CLEARANCE' ? '清仓优先' : '按权重随机' }}</dd><template v-if="form.mode === 'PRESET'"><dt>每批数量</dt><dd>{{ form.preset_quantity || '待填写' }}袋</dd><dt>每袋成本上限</dt><dd>{{ Number(form.max_cost) ? `¥${form.max_cost}` : '不限制' }}</dd></template></dl><p class="hint">权重不等于固定出现比例。需要每批固定袋数时，选择“分货时预先确定内容”。</p></aside>
    </div>
    <div class="editor-footer"><span>{{ dirty ? '草稿有未保存修改' : '当前草稿已保存' }}</span><div><el-button v-if="canEdit" :loading="busy" :disabled="loading || !!error" @click="save('draft')">保存草稿</el-button><el-button v-if="canEdit" type="primary" :loading="busy" :disabled="loading || !!error" @click="save('publish')">发布新版本</el-button></div></div>
    <el-dialog title="选择普通实物候选商品" :visible.sync="picker" width="min(1000px,96vw)" append-to-body :close-on-click-modal="false"><el-form :inline="true" size="small"><el-form-item><el-select v-model="searchField"><el-option label="商品名称" value="goodsName"/><el-option label="完整SKU" value="skuSn"/></el-select></el-form-item><el-form-item><el-input v-model.trim="keyword" placeholder="输入关键字，回车搜索" @keyup.enter.native="searchCandidates(true)"/></el-form-item><el-button size="small" :loading="searching" @click="searchCandidates(true)">搜索</el-button></el-form><el-alert v-if="searchError" title="候选商品加载失败，请重新搜索" type="error" :closable="false"/><el-table ref="candidateTable" v-loading="searching" :data="choices" row-key="skuSn" @selection-change="selected = $event"><el-table-column type="selection" width="45" :selectable="g => !skus.includes(g.skuSn)"/><el-table-column label="商品" prop="goodsName" min-width="220"/><el-table-column label="SKU" prop="skuSn" min-width="180"/><el-table-column label="规格" min-width="130"><template slot-scope="s">{{ s.row.colorName }} {{ s.row.sizeName }}</template></el-table-column><el-table-column label="说明" width="100"><template slot-scope="s">{{ skus.includes(s.row.skuSn) ? '已在规则中' : '' }}</template></el-table-column></el-table><pagination v-show="choiceTotal > 0" :total="choiceTotal" :page.sync="searchPage" :limit.sync="searchSize" @pagination="searchCandidates(false)"/><span slot="footer"><el-button @click="picker = false">返回</el-button><el-button type="primary" :disabled="!selected.length || searching" @click="addSelected">添加{{ selected.length }}种候选</el-button></span></el-dialog>
  </div>
</template>
<script>
import request from '@/utils/request'
import { getInfo, listInfo } from '@/api/goods/info'
import { checkPermi } from '@/utils/permission'
import LuckyBagLedger from '@/views/oms/inventory/LuckyBagLedger'
import LuckyBagTrialDiagnostics from './LuckyBagTrialDiagnostics'
import { emptyLuckyBag, candidateSkus, luckySummary, luckyValidation, luckyQuotaSummary, luckyStockPrecheck, luckyTrialStatus } from './luckyBagPresentation'
export default {
  name: 'LuckyBagEditor', components: { LuckyBagLedger, LuckyBagTrialDiagnostics },
  data: () => ({ loading: false, busy: false, error: '', goods: {}, form: emptyLuckyBag(), original: '', revision: 0, draftRevision: 0, published: null, tab: 'basic', sequence: 0, attemptedValidation: false, picker: false, pickerGroup: null, keyword: '', searchField: 'goodsName', searchPage: 1, searchSize: 20, searching: false, searchError: false, searchSequence: 0, choices: [], choiceTotal: 0, selected: [], warehouses: [], warehouseError: false, trialStores: [], trialQuantity: 1, trialBusy: false, trialError: '', trialResult: [], trialFetchedAt: 0, stockRows: [], stockLoading: false, stockError: '', stockCheckedAt: '', stockFetchedScope: '', stockFetchedAt: 0, activeStockStore: '', stockSequence: 0, stockClock: Date.now(), stockTimer: null, stockClockTimer: null }),
  computed: {
    canEdit() { return checkPermi(['goods:info:edit']) }, canCheckStock() { return checkPermi(['wmsInventory:inventory:list', 'ruleStock:info:list']) },
    skus() { return candidateSkus(this.form) }, summary() { return luckySummary(this.form) }, configurationIssue() { return luckyValidation(this.form) }, quotaSummaries() { return this.form.groups.map(g => luckyQuotaSummary(this.form, g)) },
    dirty() { return !!this.original && this.original !== JSON.stringify(this.form) }, hasFixed() { return this.form.groups.some(g => g.candidates.some(c => c.fixed_quantity != null)) },
    stockScope() { return this.canCheckStock && this.trialStores.length && this.skus.length && this.skus.length <= 200 ? JSON.stringify({ id: this.goods.id, skus: [...new Set(this.skus)].sort(), stores: [...new Set(this.trialStores)].sort() }) : '' },
    stockStale() { return this.stockFetchedAt > 0 && this.stockClock - this.stockFetchedAt >= 30000 },
    trialStale() { return this.trialFetchedAt > 0 && this.stockClock - this.trialFetchedAt >= 30000 },
    stockChecks() { return !this.stockLoading && this.stockFetchedScope === this.stockScope ? this.stockRows.filter(w => w.code === 'CHECKED').map(w => luckyStockPrecheck(this.form, w, this.form.mode === 'PRESET' ? this.form.preset_quantity : this.trialQuantity)) : [] },
    stockViews() { return !this.stockLoading && this.stockFetchedScope === this.stockScope ? this.stockRows.map(w => this.stockChecks.find(s => s.store_code === w.store_code) || w) : [] },
    activeStockCheck() { return this.stockChecks.find(w => w.store_code === this.activeStockStore) || null },
    activeStockFailure() { return !this.stockLoading && this.stockFetchedScope === this.stockScope ? this.stockRows.find(w => w.store_code === this.activeStockStore && w.code === 'CHECK_FAILED') : null },
    activeCandidateStock() { const out = {}; if (this.activeStockCheck) this.activeStockCheck.groups.forEach(g => g.candidates.forEach(c => { out[c.sku_sn] = c })); return out }
  },
  watch: { '$route.query.id'() { this.load() }, form: { deep: true, handler() { this.trialResult = []; this.trialError = '' } }, trialStores: { deep: true, handler() { this.trialResult = []; this.trialError = ''; if (!this.trialStores.includes(this.activeStockStore)) this.activeStockStore = this.trialStores[0] || '' } }, trialQuantity() { this.trialResult = []; this.trialError = '' }, 'form.preset_quantity'(value) { if (this.form.mode === 'PRESET') this.trialQuantity = value || 1 }, 'form.mode'(value) { if (value === 'PRESET') this.trialQuantity = this.form.preset_quantity || 1 }, stockScope() { this.scheduleStockCheck() }, tab(value) { if (value === 'contents' || value === 'preview') this.refreshStockIfStale() } },
  created() { this.load(); if (checkPermi(['wmsInventory:inventory:list', 'ruleStock:info:list'])) this.loadWarehouses() },
  mounted() { this.stockClockTimer = setInterval(() => { this.stockClock = Date.now() }, 5000); window.addEventListener('focus', this.refreshStockIfStale) },
  beforeDestroy() { this.sequence++; this.searchSequence++; this.stockSequence++; clearTimeout(this.stockTimer); clearInterval(this.stockClockTimer); window.removeEventListener('focus', this.refreshStockIfStale) },
  beforeRouteUpdate(to, from, next) { if (!this.dirty) return next(); this.$confirm('草稿修改尚未保存，确认切换商品？', '切换福袋').then(() => next()).catch(() => next(false)) },
  beforeRouteLeave(to, from, next) { if (!this.dirty) return next(); this.$confirm('草稿修改尚未保存，确认离开？', '离开福袋配置', { type: 'warning' }).then(() => next()).catch(() => next(false)) },
  methods: {
    trialStatus: luckyTrialStatus,
    stockRow(candidate) { return this.activeCandidateStock[candidate.sku_sn] || null },
    groupStock(group) { return this.activeStockCheck && this.activeStockCheck.groups.find(g => g.key === group.key) },
    stockExplanation(row) { return `正品实物${row.physical_quantity || 0}件，仓库锁定${row.locked_quantity || 0}件，另扣公共订单需求${row.public_reserved_deduction || 0}件；尚未定位仓库的公共需求按保守口径扣除。新增福袋可用${row.available}件。` },
    focusStockStores() { this.$nextTick(() => { const input = this.$el.querySelector('.stock-check-controls .el-select__input'); if (input) input.click() }) },
    scheduleStockCheck() { clearTimeout(this.stockTimer); this.stockSequence++; this.stockRows = []; this.stockLoading = false; this.stockError = ''; this.stockFetchedScope = ''; this.stockFetchedAt = 0; if (this.stockScope) this.stockTimer = setTimeout(() => this.refreshStock(), 300) },
    refreshStockIfStale() { if (this.stockScope && !this.stockLoading && (this.stockFetchedScope !== this.stockScope || Date.now() - this.stockFetchedAt >= 30000)) this.refreshStock() },
    async refreshStock() { if (!this.stockScope) return; clearTimeout(this.stockTimer); const scope = this.stockScope, seq = ++this.stockSequence; this.stockLoading = true; this.stockError = ''; this.trialResult = []; try { const r = await request({ url: '/inventory/lucky-bags/stock-check', method: 'post', data: { skus: [...new Set(this.skus)], stores: [...new Set(this.trialStores)] } }); if (scope !== this.stockScope || seq !== this.stockSequence) return; this.stockRows = r.data.warehouses; this.stockCheckedAt = r.data.checked_at; this.stockFetchedScope = scope; this.stockFetchedAt = Date.now(); this.stockClock = Date.now(); if (!this.trialStores.includes(this.activeStockStore)) this.activeStockStore = this.trialStores[0] || '' } catch (_) { if (scope === this.stockScope && seq === this.stockSequence) { this.stockRows = []; this.stockFetchedScope = ''; this.stockError = '库存查询失败，不能判断是否缺货。请刷新重试；持续失败时检查查询权限及库存服务。' } } finally { if (seq === this.stockSequence) this.stockLoading = false } },
    async load() { const id = Number(this.$route.query.id), seq = ++this.sequence; if (!Number.isSafeInteger(id) || id < 1) { this.error = '请选择要配置的福袋商品'; return } this.loading = true; this.error = ''; try { const [g, r] = await Promise.all([getInfo(id), request({ url: `/goods/info/${id}/lucky-bag`, method: 'get' })]); if (seq !== this.sequence) return; this.goods = g.data; this.hydrate(r.data) } catch (_) { if (seq === this.sequence) this.error = '福袋资料加载失败，请重试' } finally { if (seq === this.sequence) this.loading = false } },
    hydrate(data) { this.revision = Number(data.revision); this.draftRevision = Number(data.draft_revision); this.published = data.published; this.form = { ...emptyLuckyBag(), ...JSON.parse(JSON.stringify(data.draft)) }; this.form.max_cost = Number(this.form.max_cost || 0); this.form.groups.forEach(g => g.candidates.forEach(c => { c.fixed_quantity = c.fixed_quantity == null ? null : Number(c.fixed_quantity) })); this.original = JSON.stringify(this.form); this.trialResult = []; this.attemptedValidation = false },
    addGroup() { this.form.groups.push({ key: `g${Date.now()}_${this.form.groups.length}`, name: '', candidates: [] }) },
    quotaMode(candidate) { return candidate.fixed_quantity == null ? 'AUTO' : candidate.fixed_quantity === 0 ? 'EXCLUDE' : 'FIXED' },
    setQuotaMode(candidate, mode) { this.$set(candidate, 'fixed_quantity', mode === 'AUTO' ? null : mode === 'EXCLUDE' ? 0 : candidate.fixed_quantity > 0 ? candidate.fixed_quantity : 1) },
    async clearConstraints() { try { await this.$confirm('清除草稿中的固定数量与成本上限？已发布版本保持原记录。', '清除预制约束'); this.form.max_cost = 0; this.form.preset_quantity = 0; this.form.groups.forEach(g => g.candidates.forEach(c => { c.fixed_quantity = null })) } catch (_) { /* Keep the draft. */ } },
    validate() { this.attemptedValidation = true; const result = this.configurationIssue; if (!result) return true; this.tab = result.tab; this.$message.warning('配置未通过，请查看页面中的具体说明；尚未检查库存。'); return false },
    async save(action) { if (this.busy || !this.canEdit || (action === 'publish' && !this.validate())) return; this.busy = true; try { const r = await request({ url: `/goods/info/${this.goods.id}/lucky-bag/${action}`, method: 'post', data: { ...this.form, revision: this.revision, draft_revision: this.draftRevision } }); this.hydrate(r.data); this.$message.success(action === 'publish' ? '福袋新版本已发布' : '福袋草稿已保存') } finally { this.busy = false } },
    openPicker(group) { this.pickerGroup = group; this.picker = true; this.keyword = ''; this.choices = []; this.choiceTotal = 0; this.selected = [] },
    async searchCandidates(reset) { if (!this.keyword) return this.$message.warning('请输入商品名称或完整SKU'); if (reset) this.searchPage = 1; const seq = ++this.searchSequence; this.searching = true; this.searchError = false; try { const r = await listInfo({ [this.searchField]: this.keyword, isFd: 0, isPackage: 0, pageNum: this.searchPage, pageSize: this.searchSize }); if (seq !== this.searchSequence) return; this.choices = r.rows; this.choiceTotal = r.total; this.selected = [] } catch (_) { if (seq === this.searchSequence) this.searchError = true } finally { if (seq === this.searchSequence) this.searching = false } },
    addSelected() { if (this.skus.length + this.selected.length > 200) return this.$message.warning('候选商品合计最多200种'); this.selected.forEach(g => this.pickerGroup.candidates.push({ sku_sn: g.skuSn, goods_name: g.goodsName, weight: 1, clearance_priority: 0, fixed_quantity: null })); this.picker = false },
    async loadWarehouses() { this.warehouseError = false; try { this.warehouses = (await request({ url: '/inventory/lucky-bags/stores', method: 'get' })).data } catch (_) { this.warehouseError = true } },
    trialSignature() { return JSON.stringify({ definition: this.form, stores: this.trialStores, quantity: this.form.mode === 'PRESET' ? this.form.preset_quantity : this.trialQuantity, goodsId: this.goods.id, sequence: this.sequence }) },
    async trial() { if (this.trialBusy || !this.validate()) return; const signature = this.trialSignature(); const data = { definition: JSON.parse(JSON.stringify(this.form)), stores: [...this.trialStores], quantity: this.form.mode === 'PRESET' ? this.form.preset_quantity : this.trialQuantity }; this.trialBusy = true; this.trialError = ''; this.trialResult = []; try { const r = await request({ url: '/inventory/lucky-bags/trial', method: 'post', data }); if (signature === this.trialSignature()) { this.trialResult = r.data.warehouses; this.trialFetchedAt = Date.now(); this.stockClock = Date.now() } } catch (_) { if (signature === this.trialSignature()) this.trialError = '试算请求未完成，库存是否充足尚未确认，请重试；持续失败时检查仓库权限及服务状态。' } finally { this.trialBusy = false } }
  }
}
</script>
